/* حماية PIN محلية */
function simplePinHash(pin){
 let h=2166136261;
 for(let i=0;i<pin.length;i++){h^=pin.charCodeAt(i);h=Math.imul(h,16777619)}
 return (h>>>0).toString(16);
}
